#ifndef ARENA_H
#define ARENA_H

#include <stdint.h>

// An arena is one closed room (DESIGN.md 4.6): floor, collision, occlusion, where the player
// starts and which enemies fight there. The data is generated by tools/bake_arena.py and the
// runtime reads everything through `g_arena`, so arenas can be swapped without touching code.

#define COLLISION_SCALE 4        // world px per collision cell

#define ARENA_ENEMY_CHARGER 1    // same values as EnemyType (checked in gameplay.c)
#define ARENA_ENEMY_SHOOTER 2

// Horizontal run of occluding pixels; depth is the world Y of the floor point under the
// visible surface (an actor whose feet are above it is hidden).
typedef struct {
    uint16_t x;
    uint16_t y;
    uint16_t length;
    int16_t depth;
} DungeonOcclusionRun;

typedef struct {
    uint8_t type;                // ARENA_ENEMY_*
    uint16_t x;                  // spawn point, world px (feet)
    uint16_t y;
} ArenaEnemy;

typedef struct {
    const char *name;
    uint16_t world_w, world_h;           // px, multiples of 8
    uint16_t collision_w, collision_h;   // cells of COLLISION_SCALE px
    uint16_t map_w, map_h;               // floor tilemap size in 8x8 tiles
    uint16_t num_tiles;                  // distinct tiles in `tiles`
    uint16_t player_x, player_y;         // start, world px (feet)
    uint16_t num_enemies;
    const uint8_t *collision;            // 2 bits per cell: 0 free, 3 solid
    const uint16_t *palette;             // 256 BGR555 entries
    const uint8_t (*tiles)[64];          // 8bpp tile data
    const uint16_t *map;                 // map_w * map_h tile ids, row-major
    const DungeonOcclusionRun *occlusion_runs;
    const uint32_t *occlusion_row_start; // world_h + 1 entries
    const ArenaEnemy *enemies;
} Arena;

extern const Arena *const g_arenas[];    // generated, in play order
extern const int g_num_arenas;

// The arena all gameplay, collision, navigation and rendering code reads.
extern const Arena *g_arena;
void arena_select(int index);

#endif // ARENA_H
